import { MeshBasicNodeMaterial } from 'three/webgpu';
import { color, mix, uv } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, CircleGeometry, BoxGeometry, Color } = ctx.THREE;
  const root = new Group();
  root.name = 'hero-showpiece';

  const timelines = [];
  const primitiveResults = [];
  const ownedTextures = [];

  const backdropMaterial = new MeshBasicNodeMaterial({
    transparent: false,
    depthWrite: false
  });
  backdropMaterial.colorNode = mix(
    color('#0b0b10'),
    color('#16161d'),
    uv().y
  );

  const backdrop = new Mesh(
    new PlaneGeometry(7, 6),
    backdropMaterial
  );
  backdrop.name = 'engineered-gradient-backdrop';
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  const surfaceMaterial = new MeshBasicNodeMaterial({
    color: '#16161d',
    transparent: true,
    opacity: 0.96
  });

  const surface = new Mesh(
    new PlaneGeometry(5.35, 3.7),
    surfaceMaterial
  );
  surface.name = 'machined-surface';
  surface.position.set(0, 0, -1.25);
  root.add(surface);

  const contactShadowMaterial = new MeshBasicNodeMaterial({
    color: '#0b0b10',
    transparent: true,
    opacity: 0.5,
    depthWrite: false
  });

  const contactShadow = new Mesh(
    new CircleGeometry(1.65, 64),
    contactShadowMaterial
  );
  contactShadow.name = 'contact-shadow';
  contactShadow.scale.set(1.55, 0.28, 1);
  contactShadow.position.set(0, -1.55, -0.7);
  root.add(contactShadow);

  const accentMaterial = new MeshBasicNodeMaterial({
    color: '#ff2a38',
    transparent: true,
    opacity: 0.92
  });

  const accentBar = new Mesh(
    new BoxGeometry(0.055, 2.65, 0.035),
    accentMaterial
  );
  accentBar.name = 'signal-red-accent';
  accentBar.position.set(-2.72, 0.05, -0.25);
  root.add(accentBar);

  const paperMaterial = new MeshBasicNodeMaterial({
    color: '#e8ecf2',
    transparent: true,
    opacity: 0.72
  });

  const paperMark = new Mesh(
    new BoxGeometry(0.42, 0.018, 0.018),
    paperMaterial
  );
  paperMark.name = 'paper-highlight';
  paperMark.position.set(2.34, -1.12, -0.18);
  root.add(paperMark);

  const subjectMaterial = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
    alphaTest: 0.01
  });

  const subject = new Mesh(
    new PlaneGeometry(4.8, 3),
    subjectMaterial
  );
  subject.name = 'floating-accent-sprite';
  subject.position.set(0, 0.08, 0);
  subject.renderOrder = 2;
  subject.onBeforeRender = (_renderer, _scene, camera) => {
    subject.quaternion.copy(camera.quaternion);
  };
  root.add(subject);

  const imageUrl = config?.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl)
      .then((texture) => {
        if (!texture) return;

        ownedTextures.push(texture);

        if ('colorSpace' in texture && ctx.THREE.SRGBColorSpace) {
          texture.colorSpace = ctx.THREE.SRGBColorSpace;
        }

        const image = texture.image;
        const imageWidth = image?.width || 512;
        const imageHeight = image?.height || 320;
        const source = config?.atlasRegion || {
          x: 0,
          y: 0,
          width: 512,
          height: 320
        };

        texture.wrapS = ctx.THREE.ClampToEdgeWrapping;
        texture.wrapT = ctx.THREE.ClampToEdgeWrapping;
        texture.offset.set(
          source.x / imageWidth,
          1 - ((source.y + source.height) / imageHeight)
        );
        texture.repeat.set(
          source.width / imageWidth,
          source.height / imageHeight
        );
        texture.needsUpdate = true;

        subject.geometry.dispose();
        subject.geometry = new PlaneGeometry(
          4.8,
          4.8 * (source.height / source.width)
        );
        subjectMaterial.map = texture;
        subjectMaterial.needsUpdate = true;
      })
      .catch(() => {});
  }

  const handlers = {};

  root.userData.handlers = handlers;
  root.userData.cleanup = () => {
    if (root.userData.cleaned) return;
    root.userData.cleaned = true;

    for (const result of primitiveResults) {
      result?.cleanup?.();
      result?.timeline?.kill?.();
    }

    for (const timeline of timelines) {
      timeline?.kill?.();
    }

    root.traverse((object) => {
      if (object.geometry?.dispose) object.geometry.dispose();

      const material = object.material;
      if (Array.isArray(material)) {
        for (const item of material) item?.dispose?.();
      } else {
        material?.dispose?.();
      }
    });

    subject.onBeforeRender = null;
    root.removeFromParent();
  };

  return root;
}
